package main

import "fmt"

const (
	Read  = 1 << 0 // 0b001
	Write = 1 << 1 // 0b010
	Exec  = 1 << 2 // 0b100
)

func main() {
	perm := Read | Write    // 0b011 = 3
	perm = perm &^ Write    // AND NOT clears the Write bit -> 0b001
	fmt.Printf("%03b\n", perm) // 001
}

